<script setup lang="ts">
import type { Interests,InterestRule } from '../../../../packages/contracts/src/interests';
type Choice={descendantIds:string[];coveredBy:string[];id:string;label:string;kind:string;is_fictional?:boolean;hasChildren:boolean;breadcrumb:string[];competitions:{value:string;label:string}[]};
const member=useMember(),route=useRoute();const saved=ref<Interests|null>(null),rules=ref<InterestRule[]>([]),message=ref(''),busy=ref(false),conflict=ref(false),q=ref(''),trail=ref<Choice[]>([]);
const search=ref('');let searchTimer:ReturnType<typeof setTimeout>|undefined;watch(q,value=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{search.value=value;},180);});onBeforeUnmount(()=>clearTimeout(searchTimer));
const parent=computed(()=>trail.value.at(-1)?.id||'');const {data,status}=await useFetch<{data:Choice[]}>('/api/v1/interests/catalogue',{query:{parent,q:search},watch:[parent,search]});
const choices=computed(()=>data.value?.data||[]);const labels=useState<Record<string,string>>('interest-labels',()=>({}));watch(choices,cs=>{for(const c of cs)labels.value[c.id]=c.label;},{immediate:true});
const dirty=ref(false);const loadingSaved=computed(()=>!member.checked.value||!!member.session.value&&!saved.value);
const preview=ref<{headline:string;slug:string;reason:{label:string}}[]|null>(null);
async function previewChoices(){if(!saved.value)return;try{preview.value=(await member.mutate<{data:NonNullable<typeof preview.value>}>('/api/v1/me/interest-preview','POST',{revision:saved.value.revision,status:'completed',rules:rules.value,hiddenStories:saved.value.hiddenStories})).data;}catch(e){message.value=memberError(e);}}
function scope(target:string,value:string){dirty.value=true;const r=rules.value.find(r=>r.target===target);if(r){if(value)r.competition=value;else delete r.competition;}}
onMounted(async()=>{await member.refresh();if(!member.session.value)return;try{saved.value=(await $fetch<{data:Interests}>('/api/v1/me/interests')).data;Object.assign(labels.value,saved.value.labels||{});if(!dirty.value)rules.value=JSON.parse(JSON.stringify(saved.value.rules));}catch(e){message.value=memberError(e);}});
function choose(c:Choice,action:'follow'|'mute'){dirty.value=true;const previous=rules.value.find(r=>r.target===c.id);rules.value=rules.value.filter(r=>r.target!==c.id);if(previous?.action!==action)rules.value.push({target:c.id,action});}
async function save(next:'completed'|'skipped'='completed'){if(!saved.value||busy.value||conflict.value)return;busy.value=true;message.value='';try{saved.value=(await member.mutate<{data:Interests}>('/api/v1/me/interests','PUT',{revision:saved.value.revision,status:next,rules:next==='skipped'?[]:rules.value,hiddenStories:saved.value.hiddenStories})).data;rules.value=JSON.parse(JSON.stringify(saved.value.rules));dirty.value=false;message.value='Your interests are saved. A new For you edition will use these choices.';if(route.query.setup)await navigateTo(readerReturn(route.query.returnTo)||'/');}catch(e){conflict.value=(e as {statusCode?:number}).statusCode===409;message.value=memberError(e)+' Your unsaved choices remain here.';}finally{busy.value=false;}}
async function reviewConflict(){const current=(await $fetch<{data:Interests}>('/api/v1/me/interests')).data;saved.value=current;conflict.value=false;message.value=`Saved account currently has ${current.rules.length} rules. Your draft is unchanged. Save only if you want to replace those rules.`;}
useHead({title:'Your interests — The Aggregator'});
</script>
<template><section class="interest-editor"><p class="eyebrow">Your edition</p><h1>{{ route.query.setup?'Choose what interests you':'Your interests' }}</h1><p>Optional, explicit choices. Opening a group does not follow it. Interests are private and independent of listening history.</p><p v-if="member.checked.value&&!member.session.value"><NuxtLink to="/sign-in?returnTo=/preferences">Sign in to save interests</NuxtLink>. You can browse without an account.</p><p v-if="saved?.status==='legacy'">Your existing account is unchanged. Set up interests whenever you wish, or skip.</p>
<div class="interest-layout"><section aria-label="Browse interests"><label>Find a topic or team<input v-model="q" class="field-input" type="search" maxlength="120" placeholder="Football, Man City, science…"></label><nav aria-label="Interest path"><button class="control control--quiet" @click="trail=[];q=''">All subjects</button><button v-for="(c,i) in trail" :key="c.id" class="control control--quiet" @click="trail=trail.slice(0,i+1);q=''">{{ c.label }}</button></nav><p v-if="status==='pending'" role="status">Finding interests…</p><p v-if="loadingSaved" role="status">Loading saved interests before showing selections…</p><div v-if="!loadingSaved&&trail.length&&!q" class="broad-choice"><label class="interest-tile" :class="{selected:rules.some(r=>r.target===trail.at(-1)!.id&&r.action==='follow')}"><input type="checkbox" :checked="rules.some(r=>r.target===trail.at(-1)!.id&&r.action==='follow')" @change="choose(trail.at(-1)!,'follow')"><span>All {{ trail.at(-1)!.label }}</span></label></div><ul v-if="!loadingSaved" class="interest-list"><li v-for="c in choices" :key="c.id"><button v-if="c.hasChildren" class="category-disclosure" :aria-label="`Explore ${c.label}`" @click="trail.push(c);q=''">{{ c.label }} <small v-if="rules.some(r=>c.descendantIds?.includes(r.target))">{{ rules.filter(r=>c.descendantIds?.includes(r.target)).length }} choices within</small><ControlChevron/></button><label class="interest-tile" :class="{selected:rules.some(r=>r.target===c.id&&r.action==='follow'),muted:rules.some(r=>r.target===c.id&&r.action==='mute')}"><input type="checkbox" :checked="rules.some(r=>r.target===c.id&&r.action==='follow')" @change="choose(c,'follow')"><span>{{ c.hasChildren?'All ':'' }}{{ c.label }}<small>{{ c.kind }}{{ c.is_fictional?' · fictional demo':'' }}<span v-if="q"> · {{ c.breadcrumb.join(' / ') }}</span></small></span></label><p v-if="!rules.some(r=>r.target===c.id)&&c.coveredBy?.some(id=>rules.some(r=>r.target===id&&r.action==='follow'&&!r.competition))" class="metadata">Included through a broad follow. This tile is not explicitly selected; selecting it adds its own follow.</p><details class="interest-exclusion"><summary>Exclusion and coverage</summary><button class="control control--quiet" :aria-pressed="rules.some(r=>r.target===c.id&&r.action==='mute')" @click="choose(c,'mute')">{{ rules.some(r=>r.target===c.id&&r.action==='mute')?'Remove mute':'Mute' }}</button><NuxtLink :to="`/interests/${encodeURIComponent(c.id)}`">View coverage</NuxtLink></details><ControlSelect v-if="c.kind===`team`&&rules.some(r=>r.target===c.id)" label="Team coverage scope" :model-value="rules.find(r=>r.target===c.id)?.competition||``" :options="[{value:``,label:`Across all competitions`},...c.competitions]" @update:model-value="scope(c.id,$event)"/></li></ul><p v-if="!choices.length">No matching concepts. Try another name. This catalogue does not include every team.</p></section>
<aside aria-label="Unsaved choices"><h2>Your choices</h2><p>{{ rules.length }} explicit choices · {{ dirty?'Unsaved draft':'Saved selections' }}</p><p>Preview: only stories materially matching these interests appear in For you. Muted subjects take priority. Most real entities have no eligible fictional coverage.</p><ul><li v-for="r in rules" :key="r.target">{{ r.action }}: {{ labels[r.target]||r.target }}<span v-if="r.competition"> · only {{ labels[r.competition]||r.competition }}</span> <button class="control control--quiet" @click="dirty=true;rules=rules.filter(x=>x!==r)">Remove</button></li></ul><p v-if="!rules.length">No interests selected. You can save this choice or use Top stories.</p><button class="control" :disabled="!saved" @click="previewChoices">Preview matching stories</button><div v-if="preview"><p v-if="!preview.length">No matching eligible stories. No wider interests are silently added.</p><p v-for="a in preview" :key="a.slug"><NuxtLink :to="`/articles/${a.slug}`">{{ a.headline }}</NuxtLink> — {{ a.reason.label }}</p></div><div class="member-actions"><button class="control control--primary" :disabled="!saved||busy||conflict" @click="save()">Save interests</button><button class="control control--quiet" :disabled="!saved||busy" @click="dirty=true;rules=[]">Clear interest choices</button><button class="control control--quiet" :disabled="!saved||busy||conflict" @click="save('skipped')">Skip setup</button></div><button class="control control--quiet" :disabled="!saved||busy" @click="rules=JSON.parse(JSON.stringify(saved!.rules));dirty=false">Cancel unsaved changes</button><button v-if="conflict" class="control" @click="reviewConflict">Review current revision, keep my draft</button><p role="status">{{ message }}</p></aside></div></section></template>
<style scoped>.interest-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.interest-tile{display:flex;align-items:center;gap:10px;padding:14px;min-height:64px;border:1px solid var(--borderControl);border-radius:4px;background:var(--surface);cursor:pointer;line-height:1.4}.interest-tile.selected{background:#214f3c;color:#fff;border-color:#214f3c}.interest-tile.muted{border-style:dashed}.interest-tile input{width:20px;height:20px;accent-color:#214f3c;flex-shrink:0}.interest-tile:focus-within{outline:3px solid var(--focus);outline-offset:3px}.category-disclosure{display:flex;justify-content:space-between;width:100%;align-items:center;min-height:44px;padding:6px;background:transparent;color:var(--text);border:0;font:600 14px inherit;cursor:pointer}.interest-exclusion{font-size:12px;margin-block:8px}.interest-exclusion summary{cursor:pointer;min-height:28px}.broad-choice{margin-bottom:18px}.interest-list li{min-width:0}.interest-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(200px,1fr);gap:2rem;margin-top:2rem}.interest-list{list-style:none;padding:0}.interest-list li{padding:1rem 0;border-bottom:1px solid var(--borderSubtle)}small{display:block}.interest-layout aside{align-self:start}.interest-layout nav{display:flex;flex-wrap:wrap;margin-block:1rem}@media(max-width:650px){.interest-layout{grid-template-columns:1fr}}</style>
